-- Sahty initial schema bootstrap for a fresh Supabase project.
-- Generated from repository SQLAlchemy metadata plus Alembic revisions 0002-0007.
-- No sample/patient data is inserted; public API roles have no access to these tables.
CREATE TABLE public.users ( id SERIAL NOT NULL, username VARCHAR(80), email VARCHAR(120) NOT NULL, password_hash VARCHAR(256) NOT NULL, user_type VARCHAR(50) NOT NULL, is_active BOOLEAN, last_login TIMESTAMP WITHOUT TIME ZONE, login_count INTEGER, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), UNIQUE (username), UNIQUE (email) );
 CREATE TABLE public.specializations ( id SERIAL NOT NULL, name_ar VARCHAR(100) NOT NULL, name_en VARCHAR(100) NOT NULL, description TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id) );
 CREATE TABLE public.system_owners ( id SERIAL NOT NULL, full_name VARCHAR(200) NOT NULL, phone VARCHAR(20) NOT NULL, email VARCHAR(120) NOT NULL, location VARCHAR(200), facebook_profile VARCHAR(500), system_name VARCHAR(100), system_version VARCHAR(20), has_full_access BOOLEAN, can_manage_admins BOOLEAN, can_manage_system BOOLEAN, can_view_analytics BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id) );
 CREATE TABLE public.roles ( id SERIAL NOT NULL, name VARCHAR(40) NOT NULL, label_ar VARCHAR(80) NOT NULL, PRIMARY KEY (id), UNIQUE (name) );
 CREATE TABLE public.drug_database ( id SERIAL NOT NULL, trade_name VARCHAR(200) NOT NULL, generic_name VARCHAR(200) NOT NULL, manufacturer VARCHAR(200), category VARCHAR(100), therapeutic_class VARCHAR(100), available_strengths TEXT, dosage_forms TEXT, contraindications TEXT, side_effects TEXT, drug_interactions TEXT, warnings TEXT, pregnancy_category VARCHAR(10), storage_conditions TEXT, average_price FLOAT, is_available BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id) );
 CREATE TABLE public.hospitals ( id SERIAL NOT NULL, name VARCHAR(200) NOT NULL, name_en VARCHAR(200), type VARCHAR(50) NOT NULL, phone VARCHAR(20) NOT NULL, email VARCHAR(120), website VARCHAR(200), address TEXT NOT NULL, city VARCHAR(100) NOT NULL, district VARCHAR(100), postal_code VARCHAR(20), latitude FLOAT, longitude FLOAT, specializations TEXT, services TEXT, facilities TEXT, has_emergency BOOLEAN, emergency_phone VARCHAR(20), is_24_hours BOOLEAN, total_beds INTEGER, available_beds INTEGER, icu_beds INTEGER, available_icu_beds INTEGER, rating FLOAT, total_reviews INTEGER, accepted_insurance TEXT, is_active BOOLEAN, is_verified BOOLEAN, working_hours JSON, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id) );
 CREATE TABLE public.emergency_services ( id SERIAL NOT NULL, name VARCHAR(100) NOT NULL, type VARCHAR(50) NOT NULL, phone VARCHAR(20) NOT NULL, city VARCHAR(100), coverage_area TEXT, is_24_hours BOOLEAN, response_time INTEGER, description TEXT, languages_supported VARCHAR(100), is_active BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id) );
 CREATE TABLE public.egypt_governorates ( id SERIAL NOT NULL, name_ar VARCHAR(100) NOT NULL, name_en VARCHAR(100) NOT NULL, PRIMARY KEY (id), UNIQUE (name_ar), UNIQUE (name_en) );
 CREATE TABLE public.egypt_facility_types ( id SERIAL NOT NULL, name_ar VARCHAR(100) NOT NULL, name_en VARCHAR(100) NOT NULL, PRIMARY KEY (id), UNIQUE (name_ar), UNIQUE (name_en) );
 CREATE TABLE public.egypt_ownership_types ( id SERIAL NOT NULL, name_ar VARCHAR(100) NOT NULL, name_en VARCHAR(100) NOT NULL, PRIMARY KEY (id), UNIQUE (name_ar), UNIQUE (name_en) );
 CREATE TABLE public.healthcare_directory_records ( id SERIAL NOT NULL, external_id VARCHAR(120), name_ar VARCHAR(250) NOT NULL, name_en VARCHAR(250) NOT NULL, facility_type VARCHAR(80) NOT NULL, governorate VARCHAR(100) NOT NULL, city VARCHAR(150) NOT NULL, address TEXT, phone VARCHAR(250), specialty TEXT, source VARCHAR(250), latitude FLOAT, longitude FLOAT, working_hours VARCHAR(250), home_services BOOLEAN NOT NULL, emergency_24_7 BOOLEAN NOT NULL, imported_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, PRIMARY KEY (id) );
 CREATE INDEX ix_healthcare_directory_records_facility_type ON public.healthcare_directory_records (facility_type);
 CREATE INDEX ix_healthcare_directory_records_external_id ON public.healthcare_directory_records (external_id);
 CREATE INDEX ix_healthcare_directory_records_governorate ON public.healthcare_directory_records (governorate);
 CREATE INDEX ix_healthcare_directory_records_city ON public.healthcare_directory_records (city);
 CREATE TABLE public.request_rate_limits ( key VARCHAR(80) NOT NULL, window_id BIGINT NOT NULL, request_count INTEGER NOT NULL, updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, PRIMARY KEY (key) );
 CREATE TABLE public.user_sessions ( id SERIAL NOT NULL, user_id INTEGER NOT NULL, jwt_id VARCHAR(128) NOT NULL, token_hash VARCHAR(128) NOT NULL, expires_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, revoked_at TIMESTAMP WITHOUT TIME ZONE, ip_address VARCHAR(45), user_agent TEXT, created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, last_seen_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES public.users (id) );
 CREATE UNIQUE INDEX ix_user_sessions_jwt_id ON public.user_sessions (jwt_id);
 CREATE INDEX ix_user_sessions_expires_at ON public.user_sessions (expires_at);
 CREATE UNIQUE INDEX ix_user_sessions_token_hash ON public.user_sessions (token_hash);
 CREATE INDEX ix_user_sessions_user_id ON public.user_sessions (user_id);
 CREATE TABLE public.patients ( id SERIAL NOT NULL, user_id INTEGER NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, date_of_birth DATE NOT NULL, gender VARCHAR(10) NOT NULL, national_id VARCHAR(20) NOT NULL, phone VARCHAR(20) NOT NULL, email VARCHAR(120) NOT NULL, address TEXT, blood_type VARCHAR(5), height FLOAT, weight FLOAT, emergency_contact_name VARCHAR(100), emergency_contact_phone VARCHAR(20), insurance_number VARCHAR(50), insurance_provider VARCHAR(100), preferred_language VARCHAR(10), created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES public.users (id), UNIQUE (national_id) );
 CREATE TABLE public.doctors ( id SERIAL NOT NULL, user_id INTEGER NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, phone VARCHAR(20) NOT NULL, email VARCHAR(120) NOT NULL, license_number VARCHAR(50) NOT NULL, specialization VARCHAR(100) NOT NULL, sub_specialization VARCHAR(100), years_of_experience INTEGER, clinic_name VARCHAR(200), clinic_address TEXT, clinic_locations JSON, profile_image_url VARCHAR(500), hospital_affiliation VARCHAR(200), consultation_fee FLOAT, consultation_duration INTEGER, available_for_telemedicine BOOLEAN, rating FLOAT, total_reviews INTEGER, is_verified BOOLEAN, is_active BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES public.users (id), UNIQUE (license_number) );
 CREATE TABLE public.admins ( id SERIAL NOT NULL, user_id INTEGER NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, phone VARCHAR(20) NOT NULL, email VARCHAR(120) NOT NULL, admin_type VARCHAR(50) NOT NULL, department VARCHAR(100), permissions JSON, can_access_dashboard BOOLEAN, can_manage_users BOOLEAN, can_manage_doctors BOOLEAN, can_manage_hospitals BOOLEAN, can_manage_content BOOLEAN, can_view_reports BOOLEAN, can_manage_system_settings BOOLEAN, is_active BOOLEAN, is_super_admin BOOLEAN, last_login TIMESTAMP WITHOUT TIME ZONE, login_count INTEGER, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES public.users (id) );
 CREATE TABLE public.audit_logs ( id SERIAL NOT NULL, user_id INTEGER, user_email VARCHAR(120), user_type VARCHAR(50), action VARCHAR(100) NOT NULL, resource VARCHAR(100), resource_id INTEGER, description TEXT, old_values JSON, new_values JSON, ip_address VARCHAR(45), user_agent TEXT, session_id VARCHAR(100), success BOOLEAN, error_message TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES public.users (id) );
 CREATE TABLE public.provider_registrations ( id SERIAL NOT NULL, user_id INTEGER NOT NULL, provider_type VARCHAR(40) NOT NULL, legal_name VARCHAR(200) NOT NULL, license_number VARCHAR(100) NOT NULL, phone VARCHAR(30) NOT NULL, address TEXT NOT NULL, city VARCHAR(100) NOT NULL, details JSON, status VARCHAR(20) NOT NULL, review_note TEXT, reviewed_by INTEGER, reviewed_at TIMESTAMP WITHOUT TIME ZONE, created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, PRIMARY KEY (id), UNIQUE (user_id), FOREIGN KEY(user_id) REFERENCES public.users (id), FOREIGN KEY(reviewed_by) REFERENCES public.users (id) );
 CREATE TABLE public.notifications ( id SERIAL NOT NULL, user_id INTEGER NOT NULL, title VARCHAR(200) NOT NULL, message TEXT NOT NULL, type VARCHAR(50), reference_id INTEGER, reference_type VARCHAR(50), is_read BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES public.users (id) );
 CREATE TABLE public.user_roles ( id SERIAL NOT NULL, user_id INTEGER NOT NULL, role_id INTEGER NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, activated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), CONSTRAINT uq_user_role UNIQUE (user_id, role_id), FOREIGN KEY(user_id) REFERENCES public.users (id), FOREIGN KEY(role_id) REFERENCES public.roles (id) );
 CREATE TABLE public.professional_role_requests ( id SERIAL NOT NULL, user_id INTEGER NOT NULL, requested_role VARCHAR(40) NOT NULL, status VARCHAR(30) NOT NULL, submitted_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, reviewed_at TIMESTAMP WITHOUT TIME ZONE, reviewed_by INTEGER, rejection_reason TEXT, documents JSON, credentials JSON, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES public.users (id), FOREIGN KEY(reviewed_by) REFERENCES public.users (id) );
 CREATE TABLE public.nurse_profiles ( id SERIAL NOT NULL, user_id INTEGER NOT NULL, full_name VARCHAR(200) NOT NULL, qualification VARCHAR(200) NOT NULL, license_number VARCHAR(100) NOT NULL, credentials JSON, availability JSON, is_active BOOLEAN NOT NULL, created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, PRIMARY KEY (id), UNIQUE (user_id), FOREIGN KEY(user_id) REFERENCES public.users (id) );
 CREATE TABLE public.nursing_service_requests ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, nurse_id INTEGER, requested_by_user_id INTEGER, doctor_id INTEGER, requester_role VARCHAR(30) NOT NULL, provider_role VARCHAR(30) NOT NULL, request_type VARCHAR(30) NOT NULL, service_type VARCHAR(80) NOT NULL, description TEXT, address TEXT NOT NULL, scheduled_at TIMESTAMP WITHOUT TIME ZONE, status VARCHAR(30) NOT NULL, rejection_reason TEXT, visit_notes TEXT, created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.users (id), FOREIGN KEY(nurse_id) REFERENCES public.users (id), FOREIGN KEY(requested_by_user_id) REFERENCES public.users (id), FOREIGN KEY(doctor_id) REFERENCES public.users (id) );
 CREATE TABLE public.blood_inventory ( id SERIAL NOT NULL, hospital_id INTEGER NOT NULL, blood_type VARCHAR(5) NOT NULL, units_available INTEGER, units_reserved INTEGER, expiry_date DATE, days_until_expiry INTEGER, status VARCHAR(20), minimum_threshold INTEGER, last_updated TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(hospital_id) REFERENCES public.hospitals (id) );
 CREATE TABLE public.hospital_departments ( id SERIAL NOT NULL, hospital_id INTEGER NOT NULL, name VARCHAR(100) NOT NULL, name_en VARCHAR(100), description TEXT, phone VARCHAR(20), extension VARCHAR(10), floor VARCHAR(20), wing VARCHAR(50), services TEXT, equipment TEXT, head_of_department VARCHAR(100), total_doctors INTEGER, total_nurses INTEGER, working_hours JSON, is_active BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(hospital_id) REFERENCES public.hospitals (id) );
 CREATE TABLE public.egypt_cities ( id SERIAL NOT NULL, governorate_id INTEGER NOT NULL, name_ar VARCHAR(100) NOT NULL, name_en VARCHAR(100) NOT NULL, PRIMARY KEY (id), CONSTRAINT uq_egypt_city_name UNIQUE (governorate_id, name_en), FOREIGN KEY(governorate_id) REFERENCES public.egypt_governorates (id) );
 CREATE TABLE public.family_contacts ( id SERIAL NOT NULL, user_id INTEGER NOT NULL, name VARCHAR(200) NOT NULL, phone VARCHAR(30) NOT NULL, relationship VARCHAR(50), is_primary BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES public.users (id) );
 CREATE TABLE public.family_groups ( id SERIAL NOT NULL, name VARCHAR(200) NOT NULL, owner_user_id INTEGER NOT NULL, description TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(owner_user_id) REFERENCES public.users (id) );
 CREATE TABLE public.feedback ( id SERIAL NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(150), phone VARCHAR(30), type VARCHAR(30) NOT NULL, subject VARCHAR(200) NOT NULL, message TEXT NOT NULL, status VARCHAR(20), admin_notes TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, user_id INTEGER, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES public.users (id) );
 CREATE TABLE public.consultations ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, doctor_id INTEGER NOT NULL, status VARCHAR(30) NOT NULL, scheduled_at TIMESTAMP WITHOUT TIME ZONE, meeting_provider VARCHAR(40) NOT NULL, meeting_room VARCHAR(180) NOT NULL, meeting_url VARCHAR(500) NOT NULL, diagnosis TEXT, treatment_plan TEXT, prescription_data JSON, referral_type VARCHAR(40), referral_note TEXT, emergency_requested BOOLEAN NOT NULL, created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.users (id), FOREIGN KEY(doctor_id) REFERENCES public.users (id), UNIQUE (meeting_room) );
 CREATE INDEX ix_consultations_status ON public.consultations (status);
 CREATE INDEX ix_consultations_doctor_id ON public.consultations (doctor_id);
 CREATE INDEX ix_consultations_patient_id ON public.consultations (patient_id);
 CREATE TABLE public.medical_records ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, doctor_id INTEGER, visit_date TIMESTAMP WITHOUT TIME ZONE NOT NULL, diagnosis TEXT, symptoms TEXT, treatment TEXT, notes TEXT, vital_signs JSON, lab_results JSON, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id), FOREIGN KEY(doctor_id) REFERENCES public.doctors (id) );
 CREATE TABLE public.allergies ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, allergen VARCHAR(100) NOT NULL, severity VARCHAR(20), reaction TEXT, notes TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.doctor_availability ( id SERIAL NOT NULL, doctor_id INTEGER NOT NULL, day_of_week INTEGER NOT NULL, start_time TIME WITHOUT TIME ZONE NOT NULL, end_time TIME WITHOUT TIME ZONE NOT NULL, is_available BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(doctor_id) REFERENCES public.doctors (id) );
 CREATE TABLE public.system_settings ( id SERIAL NOT NULL, site_name VARCHAR(100), site_description TEXT, site_logo VARCHAR(500), site_favicon VARCHAR(500), contact_email VARCHAR(120), contact_phone VARCHAR(20), support_email VARCHAR(120), support_phone VARCHAR(20), enable_two_factor BOOLEAN, session_timeout INTEGER, max_login_attempts INTEGER, password_min_length INTEGER, enable_email_notifications BOOLEAN, enable_sms_notifications BOOLEAN, enable_push_notifications BOOLEAN, payment_currency VARCHAR(10), tax_rate FLOAT, default_language VARCHAR(10), supported_languages VARCHAR(100), maintenance_mode BOOLEAN, maintenance_message TEXT, updated_at TIMESTAMP WITHOUT TIME ZONE, updated_by INTEGER, PRIMARY KEY (id), FOREIGN KEY(updated_by) REFERENCES public.admins (id) );
 CREATE TABLE public.nursing_request_status_history ( id SERIAL NOT NULL, request_id INTEGER NOT NULL, status VARCHAR(30) NOT NULL, changed_by INTEGER NOT NULL, note TEXT, created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, PRIMARY KEY (id), FOREIGN KEY(request_id) REFERENCES public.nursing_service_requests (id), FOREIGN KEY(changed_by) REFERENCES public.users (id) );
 CREATE TABLE public.blood_donors ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, blood_type VARCHAR(5) NOT NULL, weight FLOAT NOT NULL, age INTEGER NOT NULL, is_eligible BOOLEAN, last_donation_date DATE, next_eligible_date DATE, has_chronic_diseases BOOLEAN, chronic_diseases_list TEXT, current_medications TEXT, emergency_contact BOOLEAN, available_for_emergency BOOLEAN, city VARCHAR(100), district VARCHAR(100), latitude FLOAT, longitude FLOAT, notification_enabled BOOLEAN, emergency_notification BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.blood_requests ( id SERIAL NOT NULL, patient_id INTEGER, hospital_id INTEGER, blood_type VARCHAR(5) NOT NULL, units_needed INTEGER NOT NULL, component_type VARCHAR(30) NOT NULL, is_irradiated BOOLEAN NOT NULL, urgency_level VARCHAR(20) NOT NULL, patient_name VARCHAR(200) NOT NULL, patient_age INTEGER, medical_condition TEXT, hospital_name VARCHAR(200) NOT NULL, hospital_address TEXT, contact_person VARCHAR(100), contact_phone VARCHAR(20) NOT NULL, city VARCHAR(100), district VARCHAR(100), latitude FLOAT, longitude FLOAT, status VARCHAR(20), needed_by_date TIMESTAMP WITHOUT TIME ZONE NOT NULL, description TEXT, special_requirements TEXT, transfusion_request_file_path VARCHAR(500), transfusion_request_file_name VARCHAR(200), document_status VARCHAR(30) NOT NULL, forwarded_to_centers_at TIMESTAMP WITHOUT TIME ZONE, forwarded_by_user_id INTEGER, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id), FOREIGN KEY(hospital_id) REFERENCES public.hospitals (id), FOREIGN KEY(forwarded_by_user_id) REFERENCES public.users (id) );
 CREATE TABLE public.hospital_reviews ( id SERIAL NOT NULL, hospital_id INTEGER NOT NULL, patient_id INTEGER NOT NULL, overall_rating INTEGER NOT NULL, cleanliness_rating INTEGER, staff_rating INTEGER, facilities_rating INTEGER, waiting_time_rating INTEGER, review_title VARCHAR(200), review_text TEXT, visit_date DATE, department_visited VARCHAR(100), would_recommend BOOLEAN, is_verified BOOLEAN, is_approved BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(hospital_id) REFERENCES public.hospitals (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.egypt_facilities ( id SERIAL NOT NULL, name_ar VARCHAR(250) NOT NULL, name_en VARCHAR(250) NOT NULL, governorate_id INTEGER NOT NULL, city_id INTEGER NOT NULL, facility_type_id INTEGER NOT NULL, ownership_type_id INTEGER NOT NULL, district VARCHAR(150), full_address TEXT, google_maps_url VARCHAR(500), latitude FLOAT, longitude FLOAT, phone_numbers VARCHAR(250), is_24_hours BOOLEAN NOT NULL, has_emergency_dept BOOLEAN NOT NULL, has_icu BOOLEAN NOT NULL, data_source VARCHAR(250), date_verified DATE, PRIMARY KEY (id), UNIQUE (name_en), FOREIGN KEY(governorate_id) REFERENCES public.egypt_governorates (id), FOREIGN KEY(city_id) REFERENCES public.egypt_cities (id), FOREIGN KEY(facility_type_id) REFERENCES public.egypt_facility_types (id), FOREIGN KEY(ownership_type_id) REFERENCES public.egypt_ownership_types (id) );
 CREATE TABLE public.diseases ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, name VARCHAR(200) NOT NULL, icd_code VARCHAR(20), status VARCHAR(30), severity VARCHAR(20), diagnosis_date DATE, resolution_date DATE, treating_doctor VARCHAR(200), hospital VARCHAR(200), treatment_summary TEXT, notes TEXT, attachment_data TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.surgeries ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, name VARCHAR(200) NOT NULL, surgery_type VARCHAR(100), surgery_date DATE, hospital VARCHAR(200), surgeon VARCHAR(200), anesthesia_type VARCHAR(50), duration_minutes INTEGER, outcome VARCHAR(50), complications TEXT, post_op_notes TEXT, follow_up_date DATE, notes TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.vaccinations ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, vaccine_name VARCHAR(200) NOT NULL, disease_prevented VARCHAR(200), dose_number INTEGER, total_doses INTEGER, date_given DATE, next_due_date DATE, provider VARCHAR(200), batch_number VARCHAR(100), administration_site VARCHAR(100), reaction TEXT, notes TEXT, attachment_data TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.lab_tests ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, test_name VARCHAR(200) NOT NULL, test_category VARCHAR(100), test_date DATE, lab_name VARCHAR(200), ordering_doctor VARCHAR(200), result_value VARCHAR(200), unit VARCHAR(50), reference_range VARCHAR(200), status VARCHAR(20), interpretation TEXT, notes TEXT, attachment_data TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.radiology_scans ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, scan_type VARCHAR(50) NOT NULL, body_part VARCHAR(200) NOT NULL, scan_date DATE, facility VARCHAR(200), radiologist VARCHAR(200), ordering_doctor VARCHAR(200), reason TEXT, findings TEXT, impression TEXT, recommendation TEXT, notes TEXT, attachment_data TEXT, report_data TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.blood_gas_readings ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, reading_date DATE, reading_time VARCHAR(10), mode VARCHAR(50), ph VARCHAR(20), pco2 VARCHAR(20), hco3 VARCHAR(20), o2 VARCHAR(20), spo2 VARCHAR(20), k VARCHAR(20), lactate VARCHAR(20), notes TEXT, attachment_data TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.ecg_records ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, ecg_date DATE, facility VARCHAR(200), ordering_doctor VARCHAR(200), findings TEXT, notes TEXT, attachment_data TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.medical_history ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, smoking_status VARCHAR(30), smoking_years INTEGER, alcohol_use VARCHAR(30), physical_activity VARCHAR(30), diet_type VARCHAR(100), family_history JSON, chronic_conditions TEXT, genetic_conditions TEXT, general_notes TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), UNIQUE (patient_id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.lab_requests ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, requesting_user_id INTEGER NOT NULL, test_name VARCHAR(200) NOT NULL, tests_json TEXT, test_category VARCHAR(100), urgency VARCHAR(20), clinical_notes TEXT, ordering_doctor VARCHAR(200), lab_center_name VARCHAR(200), preparation_instructions TEXT, preparation_notes TEXT, request_doc_path VARCHAR(500), request_doc_name VARCHAR(200), scheduled_datetime TIMESTAMP WITHOUT TIME ZONE, home_collection BOOLEAN, collection_address TEXT, collection_lat FLOAT, collection_lng FLOAT, collection_date DATE, collection_time VARCHAR(10), collection_staff_name VARCHAR(200), status VARCHAR(30), approved_by_user_id INTEGER, approved_at TIMESTAMP WITHOUT TIME ZONE, approval_notes TEXT, rejection_reason TEXT, lab_name VARCHAR(200), result_value VARCHAR(200), result_unit VARCHAR(50), reference_range VARCHAR(200), result_status VARCHAR(20), result_interpretation TEXT, result_file_path VARCHAR(500), result_file_name VARCHAR(200), result_uploaded_at TIMESTAMP WITHOUT TIME ZONE, result_uploaded_by INTEGER, notified_at TIMESTAMP WITHOUT TIME ZONE, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id), FOREIGN KEY(requesting_user_id) REFERENCES public.users (id), FOREIGN KEY(approved_by_user_id) REFERENCES public.users (id), FOREIGN KEY(result_uploaded_by) REFERENCES public.users (id) );
 CREATE TABLE public.radiology_requests ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, requesting_user_id INTEGER NOT NULL, scan_type VARCHAR(50) NOT NULL, body_part VARCHAR(200) NOT NULL, body_part_code VARCHAR(80), urgency VARCHAR(20), clinical_reason TEXT, ordering_doctor VARCHAR(200), patient_weight FLOAT, requires_sedation BOOLEAN, uses_contrast BOOLEAN, preparation_required BOOLEAN, preparation_checklist_json TEXT, radiology_center_name VARCHAR(200), request_doc_path VARCHAR(500), request_doc_name VARCHAR(200), scheduled_datetime TIMESTAMP WITHOUT TIME ZONE, status VARCHAR(30), rejection_reason TEXT, image_paths_json TEXT, images_uploaded_at TIMESTAMP WITHOUT TIME ZONE, images_uploaded_by INTEGER, facility VARCHAR(200), radiologist_name VARCHAR(200), findings TEXT, impression TEXT, recommendation TEXT, report_file_path VARCHAR(500), report_file_name VARCHAR(200), report_uploaded_at TIMESTAMP WITHOUT TIME ZONE, report_uploaded_by INTEGER, shared_at TIMESTAMP WITHOUT TIME ZONE, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id), FOREIGN KEY(requesting_user_id) REFERENCES public.users (id), FOREIGN KEY(images_uploaded_by) REFERENCES public.users (id), FOREIGN KEY(report_uploaded_by) REFERENCES public.users (id) );
 CREATE TABLE public.emergency_alerts ( id SERIAL NOT NULL, user_id INTEGER NOT NULL, patient_id INTEGER, alert_type VARCHAR(30), latitude FLOAT, longitude FLOAT, location_text VARCHAR(500), emergency_type VARCHAR(100), severity VARCHAR(20), description TEXT, caller_name VARCHAR(200), caller_phone VARCHAR(30), status VARCHAR(30), family_notified BOOLEAN, notified_at TIMESTAMP WITHOUT TIME ZONE, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES public.users (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.family_members ( id SERIAL NOT NULL, group_id INTEGER NOT NULL, linked_user_id INTEGER, linked_patient_id INTEGER, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, relationship VARCHAR(50) NOT NULL, date_of_birth DATE, gender VARCHAR(10), blood_type VARCHAR(5), phone VARCHAR(20), chronic_diseases TEXT, allergies TEXT, current_medications TEXT, notes TEXT, is_active BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(group_id) REFERENCES public.family_groups (id), FOREIGN KEY(linked_user_id) REFERENCES public.users (id), FOREIGN KEY(linked_patient_id) REFERENCES public.patients (id) );
 CREATE TABLE public.consultation_messages ( id SERIAL NOT NULL, consultation_id INTEGER NOT NULL, sender_user_id INTEGER NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, PRIMARY KEY (id), FOREIGN KEY(consultation_id) REFERENCES public.consultations (id) ON DELETE CASCADE, FOREIGN KEY(sender_user_id) REFERENCES public.users (id) );
 CREATE INDEX ix_consultation_messages_consultation_id ON public.consultation_messages (consultation_id);
 CREATE INDEX ix_consultation_messages_sender_user_id ON public.consultation_messages (sender_user_id);
 CREATE TABLE public.consultation_attachments ( id SERIAL NOT NULL, consultation_id INTEGER NOT NULL, uploaded_by_user_id INTEGER NOT NULL, file_path VARCHAR(500) NOT NULL, file_name VARCHAR(255) NOT NULL, mime_type VARCHAR(120), file_size INTEGER, kind VARCHAR(40) NOT NULL, created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, PRIMARY KEY (id), FOREIGN KEY(consultation_id) REFERENCES public.consultations (id) ON DELETE CASCADE, FOREIGN KEY(uploaded_by_user_id) REFERENCES public.users (id) );
 CREATE INDEX ix_consultation_attachments_consultation_id ON public.consultation_attachments (consultation_id);
 CREATE TABLE public.appointments ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, doctor_id INTEGER NOT NULL, appointment_date TIMESTAMP WITHOUT TIME ZONE NOT NULL, duration INTEGER, appointment_type VARCHAR(20) NOT NULL, status VARCHAR(20), reason TEXT, notes TEXT, symptoms TEXT, fee FLOAT, payment_status VARCHAR(20), payment_method VARCHAR(50), meeting_link VARCHAR(500), meeting_id VARCHAR(100), reminder_sent BOOLEAN, reminder_sent_at TIMESTAMP WITHOUT TIME ZONE, for_family_member_id INTEGER, for_member_name VARCHAR(200), created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id), FOREIGN KEY(doctor_id) REFERENCES public.doctors (id), FOREIGN KEY(for_family_member_id) REFERENCES public.family_members (id) );
 CREATE TABLE public.blood_request_responses ( id SERIAL NOT NULL, request_id INTEGER NOT NULL, donor_id INTEGER NOT NULL, response_type VARCHAR(20) NOT NULL, available_date TIMESTAMP WITHOUT TIME ZONE, message TEXT, status VARCHAR(20), created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(request_id) REFERENCES public.blood_requests (id), FOREIGN KEY(donor_id) REFERENCES public.blood_donors (id) );
 CREATE TABLE public.blood_donations ( id SERIAL NOT NULL, donor_id INTEGER NOT NULL, request_id INTEGER, donation_date TIMESTAMP WITHOUT TIME ZONE NOT NULL, units_donated INTEGER, donation_type VARCHAR(20), donation_center VARCHAR(200), center_address TEXT, pre_donation_screening JSON, post_donation_tests JSON, status VARCHAR(20), rejection_reason TEXT, notes TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(donor_id) REFERENCES public.blood_donors (id), FOREIGN KEY(request_id) REFERENCES public.blood_requests (id) );
 CREATE TABLE public.family_member_health_records ( id SERIAL NOT NULL, member_id INTEGER NOT NULL, record_type VARCHAR(50) NOT NULL, title VARCHAR(200) NOT NULL, description TEXT, date DATE NOT NULL, next_due_date DATE, result TEXT, doctor_name VARCHAR(200), hospital_name VARCHAR(200), attachments TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(member_id) REFERENCES public.family_members (id) );
 CREATE TABLE public.family_health_goals ( id SERIAL NOT NULL, group_id INTEGER NOT NULL, member_id INTEGER, title VARCHAR(200) NOT NULL, description TEXT, target_date DATE, status VARCHAR(20), progress INTEGER, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(group_id) REFERENCES public.family_groups (id), FOREIGN KEY(member_id) REFERENCES public.family_members (id) );
 CREATE TABLE public.appointment_history ( id SERIAL NOT NULL, appointment_id INTEGER NOT NULL, previous_status VARCHAR(20), new_status VARCHAR(20) NOT NULL, change_reason TEXT, changed_by INTEGER, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(appointment_id) REFERENCES public.appointments (id), FOREIGN KEY(changed_by) REFERENCES public.users (id) );
 CREATE TABLE public.appointment_ratings ( id SERIAL NOT NULL, appointment_id INTEGER NOT NULL, patient_id INTEGER NOT NULL, doctor_id INTEGER NOT NULL, rating INTEGER NOT NULL, review TEXT, punctuality_rating INTEGER, communication_rating INTEGER, treatment_effectiveness INTEGER, would_recommend BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(appointment_id) REFERENCES public.appointments (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id), FOREIGN KEY(doctor_id) REFERENCES public.doctors (id) );
 CREATE TABLE public.prescriptions ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, doctor_id INTEGER NOT NULL, appointment_id INTEGER, diagnosis TEXT, notes TEXT, status VARCHAR(30) NOT NULL, pharmacy_user_id INTEGER, pharmacy_name VARCHAR(200), sent_to_pharmacy_at TIMESTAMP WITHOUT TIME ZONE, dispensed_at TIMESTAMP WITHOUT TIME ZONE, dispensed_by VARCHAR(200), valid_until DATE, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id), FOREIGN KEY(doctor_id) REFERENCES public.doctors (id), FOREIGN KEY(appointment_id) REFERENCES public.appointments (id), FOREIGN KEY(pharmacy_user_id) REFERENCES public.users (id) );
 CREATE TABLE public.medications ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, doctor_id INTEGER, prescription_id INTEGER, source VARCHAR(30), name VARCHAR(200) NOT NULL, generic_name VARCHAR(200), dosage VARCHAR(100) NOT NULL, form VARCHAR(50), frequency VARCHAR(100) NOT NULL, duration VARCHAR(100), instructions TEXT, start_date DATE NOT NULL, end_date DATE, is_active BOOLEAN, is_completed BOOLEAN, side_effects TEXT, warnings TEXT, interactions TEXT, attachment_data TEXT, notify_family BOOLEAN, notify_doctor_on_missed BOOLEAN, missed_dose_threshold INTEGER, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id), FOREIGN KEY(doctor_id) REFERENCES public.doctors (id), FOREIGN KEY(prescription_id) REFERENCES public.prescriptions (id) );
 CREATE TABLE public.pharmacy_orders ( id SERIAL NOT NULL, patient_id INTEGER NOT NULL, order_type VARCHAR(30) NOT NULL, prescription_image_path VARCHAR(500), prescription_image_name VARCHAR(200), source_prescription_id INTEGER, medications_json TEXT, preferred_pharmacy_name VARCHAR(200), preferred_pharmacy_id INTEGER, fulfillment_method VARCHAR(30), delivery_address TEXT, notes TEXT, status VARCHAR(30), dispensed_at TIMESTAMP WITHOUT TIME ZONE, cancelled_reason TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, updated_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id), FOREIGN KEY(source_prescription_id) REFERENCES public.prescriptions (id) );
 CREATE TABLE public.prescription_items ( id SERIAL NOT NULL, prescription_id INTEGER NOT NULL, drug_name VARCHAR(200) NOT NULL, generic_name VARCHAR(200), dosage VARCHAR(100) NOT NULL, form VARCHAR(50), frequency VARCHAR(100) NOT NULL, duration VARCHAR(100), quantity VARCHAR(100), instructions TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(prescription_id) REFERENCES public.prescriptions (id) );
 CREATE TABLE public.medication_schedules ( id SERIAL NOT NULL, medication_id INTEGER NOT NULL, time_of_day TIME WITHOUT TIME ZONE NOT NULL, days_of_week VARCHAR(20), reminder_enabled BOOLEAN, reminder_minutes_before INTEGER, is_active BOOLEAN, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(medication_id) REFERENCES public.medications (id) );
 CREATE TABLE public.medication_logs ( id SERIAL NOT NULL, medication_id INTEGER NOT NULL, patient_id INTEGER NOT NULL, scheduled_time TIMESTAMP WITHOUT TIME ZONE NOT NULL, actual_time TIMESTAMP WITHOUT TIME ZONE, status VARCHAR(20) NOT NULL, notes TEXT, side_effects_experienced TEXT, created_at TIMESTAMP WITHOUT TIME ZONE, PRIMARY KEY (id), FOREIGN KEY(medication_id) REFERENCES public.medications (id), FOREIGN KEY(patient_id) REFERENCES public.patients (id) );
